///
/// One name and value a document kind lists or filters on. A name may repeat
/// (a source declaration carries one `class` per class it satisfies); values
/// are text, since nothing sorts or compares them in a registry query.
///
struct DocumentField {
    std::string name_;
    std::optional<std::string> value_;

    DocumentField();
    DocumentField(const ::DocumentField *root);
    DocumentField(const std::vector<uint8_t> &bytes);
    bool operator==(const DocumentField &rhs) const;
    bool operator!=(const DocumentField &rhs) const {
        return !(*this == rhs);
    }
};

///
/// A governed document of any kind cortext keeps: a skill, a source note, an
/// exploration's program, a KPI spec, a source declaration. One platform type
/// for all of them, so a new kind is a cortext declaration rather than a
/// schema, a registry spec and a rebuild (libs/uldatacatalog/src/registry/
/// documents.design.md).
///
/// The object is a reference, like every governed kind: the document is a
/// Drive file named here by id, content revision and sha256, and the fields a
/// reader lists on are projected once per revision into the `documents`
/// registry (registry.fbs), so nothing on a read path opens the document.
///
struct GovernedDocument {
    std::optional<std::string> authored_by_;
    std::optional<ContentId> document_cid_;
    ObjectId document_id_;
    std::string document_sha256_;
    std::optional<std::vector<DocumentField>> fields_;
    std::string key_;
    std::string kind_;
    std::optional<std::string> namespace_;
    int64_t published_at_;
    std::optional<std::string> title_;

    GovernedDocument();
    GovernedDocument(const ::GovernedDocument *root);
    GovernedDocument(const std::vector<uint8_t> &bytes);
    bool operator==(const GovernedDocument &rhs) const;
    bool operator!=(const GovernedDocument &rhs) const {
        return !(*this == rhs);
    }
};

